//! Creation bytecode for local-Anvil e2e fixtures. The executor bytecode is
//! loaded from the exact-byte vendored R6-1 manifest; other constants are
//! test-only dependency fixtures and are never linked into a node binary.
#![allow(dead_code)]

use std::sync::OnceLock;

use alloy_primitives::hex;
use k256::sha2::{Digest, Sha256};
use serde_json::Value;

const R61_MANIFEST: &str = include_str!("../fixtures/r61-manifest.json");
const R61_SOURCE_COMMIT: &str = "4253d6916698b5f4fa23e87aaf780d3e11279037";
const R61_ARTIFACT_SHA256: &str =
    "3221c422e286ed92af0bb53baabd6d55a531f4477428fc2d5af58c7905a777f4";
const EXECUTE_SELECTOR: &str = "3b83f272";
const RETIRED_EXECUTE_SELECTOR: &str = "21def296";

/// Parses and seals the vendored manifest, returning its sole executor creation bytecode.
pub fn executor_creation() -> &'static str {
    static CREATION: OnceLock<String> = OnceLock::new();
    CREATION.get_or_init(|| {
        let mut manifest: Value =
            serde_json::from_str(R61_MANIFEST).expect("R6-1 manifest must be valid JSON");
        {
            let object = manifest.as_object_mut().expect("R6-1 manifest must be a JSON object");
            assert_eq!(
                object.get("generated_from_commit").and_then(Value::as_str),
                Some(R61_SOURCE_COMMIT),
                "R6-1 manifest source commit seal changed"
            );
            let declared_sha = object
                .remove("artifact_sha256")
                .and_then(|value| value.as_str().map(str::to_owned))
                .expect("R6-1 manifest artifact_sha256 must be a string");
            assert_eq!(declared_sha, R61_ARTIFACT_SHA256, "R6-1 manifest digest seal changed");
        }
        let canonical = serde_json::to_vec(&manifest)
            .expect("R6-1 manifest must have a canonical JSON representation");
        assert_eq!(
            hex::encode(Sha256::digest(canonical)),
            R61_ARTIFACT_SHA256,
            "R6-1 manifest canonical self-excluding digest mismatch"
        );
        let object = manifest.as_object().expect("R6-1 manifest must be a JSON object");

        let contracts = object
            .get("contracts")
            .and_then(Value::as_array)
            .expect("R6-1 manifest contracts must be an array");
        let mut executors = contracts.iter().filter(|contract| {
            contract.get("name").and_then(Value::as_str) == Some("BlinkAtomicExecutor")
        });
        let executor = executors.next().expect("R6-1 manifest must contain BlinkAtomicExecutor");
        assert!(executors.next().is_none(), "R6-1 manifest contains duplicate executors");
        let creation = executor
            .get("creation_bytecode_hex")
            .and_then(Value::as_str)
            .expect("BlinkAtomicExecutor creation bytecode must be a string");
        let runtime = executor
            .get("runtime_bytecode_hex")
            .and_then(Value::as_str)
            .expect("BlinkAtomicExecutor runtime bytecode must be a string");
        assert!(
            creation.starts_with("0x") && creation.len() > 2,
            "executor creation bytecode is empty"
        );
        assert!(
            runtime.starts_with("0x") && runtime.len() > 2,
            "executor runtime bytecode is empty"
        );
        hex::decode(creation).expect("executor creation bytecode must be hexadecimal");
        hex::decode(runtime).expect("executor runtime bytecode must be hexadecimal");
        assert!(
            runtime.contains(EXECUTE_SELECTOR),
            "executor runtime is missing the R6-1 dispatcher selector"
        );
        assert!(
            !runtime.contains(RETIRED_EXECUTE_SELECTOR),
            "executor runtime contains the retired dispatcher selector"
        );

        let execute = object
            .get("executor_abi")
            .and_then(Value::as_array)
            .expect("R6-1 manifest executor_abi must be an array")
            .iter()
            .find(|entry| {
                entry.get("type").and_then(Value::as_str) == Some("function")
                    && entry.get("name").and_then(Value::as_str) == Some("executeBlinkOfaAtomic")
            })
            .expect("R6-1 manifest ABI is missing executeBlinkOfaAtomic");
        let inputs = execute
            .get("inputs")
            .and_then(Value::as_array)
            .expect("executeBlinkOfaAtomic inputs must be an array");
        assert_eq!(inputs.len(), 5, "executeBlinkOfaAtomic input count changed");
        let expected_hop_schema = [
            ("adapter", "address"),
            ("pool", "address"),
            ("tokenIn", "address"),
            ("tokenOut", "address"),
            ("feeBps", "uint24"),
            ("minAmountOut", "uint256"),
            ("fundingTarget", "address"),
        ];
        for (index, hop) in inputs[..2].iter().enumerate() {
            assert_eq!(
                hop.get("type").and_then(Value::as_str),
                Some("tuple"),
                "hop {index} is not a tuple"
            );
            let components = hop
                .get("components")
                .and_then(Value::as_array)
                .expect("SwapHop components must be an array");
            assert_eq!(
                components.len(),
                expected_hop_schema.len(),
                "SwapHop must contain seven fields"
            );
            for (component, (expected_name, expected_type)) in
                components.iter().zip(expected_hop_schema)
            {
                assert_eq!(
                    component.get("name").and_then(Value::as_str),
                    Some(expected_name),
                    "SwapHop field name changed"
                );
                assert_eq!(
                    component.get("type").and_then(Value::as_str),
                    Some(expected_type),
                    "SwapHop field type changed"
                );
            }
        }
        creation.to_owned()
    })
}

